17	    /** 测试用快照构造器：按 name -> 版本（版本号，是否撤回，依赖列表）组织，版本降序排列。 */
18	    private static RepositorySnapshot snapshot(long version, Object... groups) {
19	        Map<String, List<ArtifactVersion>> map = new TreeMap<>();
20	        AtomicLong id = new AtomicLong(1);
21	        for (int i = 0; i < groups.length; i += 2) {
22	            String name = (String) groups[i];
23	            @SuppressWarnings("unchecked")
24	            List<TestVersion> versions = (List<TestVersion>) groups[i + 1];
25	            List<ArtifactVersion> list = versions.stream()
26	                    .map(v -> new ArtifactVersion(id.getAndIncrement(), name, v.version(),
27	                            v.withdrawn(), v.deps()))
28	                    .toList();
29	            map.put(name, list);
30	        }
31	        return new RepositorySnapshot(version, map);
32	    }
33	
34	    private record TestVersion(int version, boolean withdrawn, List<DependencyRange> deps) {
35	    }
36	
37	    private static TestVersion v(int version, DependencyRange... deps) {
38	        return new TestVersion(version, false, List.of(deps));
39	    }
40	
