56	    @Test
57	    void requiresBacktrackingWhenHighestCandidateConflictsLater() {
58	        // app:1 -> B[1,2] 且 C[1,1]；B2 -> C[2,2]（与 C1 冲突），必须回退到 B1。
59	        RepositorySnapshot s = snapshot(0,
60	                "app", List.of(v(1, dep("b", 1, 2), dep("c", 1, 1))),
61	                "b", List.of(v(2, dep("c", 2, 2)), v(1)),
