72	        // 贪心取 a2 将失败，必须回退到 a1/b1。
73	        RepositorySnapshot s = snapshot(0,
74	                "app", List.of(v(1, dep("a", 1, 2))),
75	                "a", List.of(v(2, dep("b", 2, 2)), v(1, dep("b", 1, 1))),
76	                "b", List.of(w(2), v(1)));
