84	        // 根 app:1 固定，a1 -> app[2,2]，但 app 只能是 1，环冲突不可行。
85	        RepositorySnapshot s = snapshot(0,
86	                "app", List.of(v(1, dep("a", 1, 1)), v(2)),
87	                "a", List.of(v(1, dep("app", 2, 2))));
88	
