93	    void supportsConsistentCycle() {
94	        // app:1 -> a[1,1]，a1 -> app[1,1]：环但区间互相满足。
95	        RepositorySnapshot s = snapshot(0,
96	                "app", List.of(v(1, dep("a", 1, 1)), v(2, dep("a", 1, 1))),
97	                "a", List.of(v(1, dep("app", 1, 1))));
