101	    }
102	
103	    @Test
104	    void selfDependencyMustMatchFixedRootVersion() {
105	        RepositorySnapshot s = snapshot(0,
106	                "app", List.of(v(2, dep("app", 2, 2)), v(1, dep("app", 1, 1))));
107	        assertThat(LockResolver.resolve(s, "app", 1)).isEqualTo(Map.of("app", 1));
108	        assertThat(LockResolver.resolve(s, "app", 2)).isEqualTo(Map.of("app", 2));
109	    }
110	
111	    @Test
112	    void selfDependencyMismatchIsInfeasible() {
113	        RepositorySnapshot s = snapshot(0,
114	                "app", List.of(v(1, dep("app", 2, 2)), v(2)));
115	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
116	    }
117	
118	    @Test
119	    void skipsWithdrawnCandidates() {
120	        // b2 已撤回，只能取 b1。
